"""Help content — the single source of truth for every explanation in the UI.

The desktop app is installed on clinic computers and configured by reception
staff, not by system administrators. Every field therefore has to answer four
questions before the user can act on it:

    این چیست؟  ->  چرا لازم است؟  ->  چه چیزی وارد کنم؟  ->  آیا کار می‌کند؟

``Help`` holds those answers as data. Widgets in ``help_widgets.py`` render
them; nothing here imports Qt, so the copy can be reviewed, translated, or
unit-tested on its own.

Two rules keep the wording consistent across the whole application:

* One concept, one label. ``TERMS`` below is the canonical vocabulary — a
  field is called «آدرس سرور» everywhere, never «هاست» in one page and
  «Endpoint» in another.
* Plain language before technical language. The technical name (``crm_port``,
  ``temperature``) belongs in ``technical``, shown only when the user opens
  the detail panel.
"""

from __future__ import annotations

from dataclasses import dataclass, field


# --------------------------------------------------------------------------- #
# canonical vocabulary
# --------------------------------------------------------------------------- #
TERMS: dict[str, str] = {
    "server_address": "آدرس سرور",
    "port": "پورت",
    "username": "نام کاربری",
    "password": "رمز عبور",
    "access_token": "توکن دسترسی",
    "api_key": "کلید API",
    "center": "مرکز",
    "timeout": "مهلت پاسخ",
    "reception": "نرم‌افزار پذیرش",
    "gateway": "درگاه",
    "brain": "مغز هوش مصنوعی",
}


# --------------------------------------------------------------------------- #
# the help record
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Help:
    """Everything the UI can say about one field, section, or page."""

    title: str
    what: str = ""
    why: str = ""
    value: str = ""
    where: str = ""
    required: bool | None = None
    warning: str = ""
    technical: str = ""
    steps: list[str] = field(default_factory=list)

    # -- rendering ---------------------------------------------------------- #
    @property
    def requirement_label(self) -> str:
        if self.required is True:
            return "الزامی"
        if self.required is False:
            return "اختیاری"
        return ""

    def summary(self) -> str:
        """One short line — used for hover tooltips."""
        return self.what or self.why or self.title

    def rows(self) -> list[tuple[str, str]]:
        """Ordered (heading, text) pairs for the detail panel."""
        pairs = [
            ("این چیست؟", self.what),
            ("چرا لازم است؟", self.why),
            ("چه چیزی وارد کنم؟", self.value),
            ("این مقدار را کجا پیدا کنم؟", self.where),
        ]
        return [(heading, text) for heading, text in pairs if text]


